procedure cell01_single_balanced {
    trigger settlement
    version "1.0.0"
    participant Payer {
        role = "payer"
        org  = "a"
    }
    participant Payee {
        role = "payee"
        org  = "b"
    }
    allow "a" with "b" {
        "a" as "payer"
        "b" as "payee"
    }
    input amount   : money
    input currency : currency
    input pid      : party
    input qid      : party
    input key      : string
    debit d {
        ledger          = "l.payer"
        owner           = "payer"
        participant     = "Payer"
        party           = %pid
        amount          = %amount
        currency        = %currency
        idempotency_key  = %key
    }
    credit c {
        ledger          = "l.payee"
        owner           = "payee"
        participant     = "Payee"
        party           = %qid
        amount          = %amount
        currency        = %currency
        idempotency_key  = %key
    }
    assert balanced
}

